function loadData_(tidy, fresh) {
  var cache = CacheService.getScriptCache(), hit = cache.get('bandData');
  if (hit && !tidy && !fresh) { try { return JSON.parse(hit); } catch (e) {} }
  var it = DriveApp.getFolderById(PAGE_FOLDER_ID).searchFiles("title contains 'data-' and trashed = false"), data = [];
  while (it.hasNext()) { var f = it.next(), n = f.getName(); if (/^data-.*\.json$/.test(n)) data.push({ f: f, n: n }); }
  data.sort(function (a, b) { return a.n < b.n ? 1 : a.n > b.n ? -1 : 0; });
  var d = null, raw = '';
  for (var i = 0; i < data.length && d === null; i++) {
    try { raw = data[i].f.getBlob().getDataAsString('UTF-8'); var x = JSON.parse(raw); if (x.members && x.sessions) d = x; } catch (e) {}
  }
  if (tidy) for (var j = 5; j < data.length; j++) { try { data[j].f.setTrashed(true); } catch (e) {} }
  if (d !== null) { try { cache.put('bandData', raw, 600); } catch (e) {} }   // tick() refreshes it every minute
  return d;
}
